function e(e,t=[]){switch(e.type){case`select_plan`:{let n=typeof e.planId==`string`?e.planId:null,r=t.find(e=>e.id===n)?.name??n;return r?`Selected ${r} coverage`:`Selected coverage`}case`set_preference`:return e.key===`renewalFrequency`?e.value===`annual`?`Set renewal to annual`:`Set renewal to monthly`:e.key===`paperless`?e.value?`Enabled paperless communication`:`Enabled paper communication`:e.key===`communication`?`Set communication to ${String(e.value)}`:`Updated a preference`;case`set_address`:return`Updated address`;case`add_dependent`:return`Added a dependent`;case`review_recipient_details`:return`Confirmed address and dependents`;case`preview_renewal`:return`Reviewed renewal summary`;case`create_confirmation`:return`Approved for 120 seconds`;case`submit_renewal`:return`Submitted renewal`;case`record_decision`:return`Recorded a decision`;default:return e.type.replaceAll(`_`,` `)}}export{e as t};